 + T([
    ("<b>pop-up adverts</b> / <b>come up</b>", "A user wants to stop unwanted adverts appearing on screen whenever they use the Internet; the answer is to go to the tools menu and disable them.", "Người dùng muốn chặn quảng cáo bật lên mỗi khi vào mạng; câu trả lời: vào menu công cụ và tắt chúng."),
    ("<b>print off</b> / <b>come on</b> / <b>go off</b>", "When printing several copies, a warning light starts working on the printer, or the printer stops working completely.", "Khi in nhiều bản, đèn cảnh báo trên máy in bật sáng, hoặc máy in tắt hẳn."),
    ("<b>call up</b>", "You can find and show the information about your printer from the control panel.", "Có thể mở thông tin về máy in từ bảng điều khiển."),
    ("<b>drop-down menu</b> / <b>type in</b>", "To make a list of choices on a website, go to the tutorial page and type your question.", "Muốn tạo danh sách lựa chọn thả xuống trên trang web, hãy vào trang hướng dẫn và gõ câu hỏi."),
    ("<b>fade in</b> / <b>fade out</b>", "Photos in a slide show gradually become brighter and then darker automatically.", "Ảnh trong trình chiếu tự động sáng dần lên rồi mờ dần đi."),
    ("<b>wipe off</b>", "In a power cut, a lot of data was removed from the hard drive; a back-up power unit can prevent this.", "Khi mất điện, nhiều dữ liệu bị xóa khỏi ổ cứng; thiết bị nguồn dự phòng có thể ngăn điều này."),
 ])
